def ladder_html(cid, c, H, BL):
    out = ''
    used = []
    texts = [' || '.join([m[0], m[1], ' '.join(m[2]), m[3], m[4]]) for m in c['mods']]
    for i, (tt, n) in enumerate(LADDER[cid], 1):
        k = pick_module(texts, tt, n, LADDER_MODULE_IDX[i-1], used); k = MODULE_OVERRIDE.get((cid, i), k); used.append(k)
        m = c['mods'][k]
        mod = (m[0], BL[k], H[k], m[1], m[2], m[3], m[4], m[5])
        on, nt = deep_slide(i, tt, n, mod, quiz_for_module(c['quiz'], k + 1))
        out += f'<details class="mod"><summary>Slide {i}. {LV[i]}: {e(tt)}</summary><p><strong>On the slide:</strong> {LV[i]} · {e(on)}</p><p><strong>Notes:</strong> {e(nt)}</p></details>'
    return out

def build(cid, c):
    mods = ''
    mm = list(c['mods'])
    mm[-1] = mm[-1][:3] + T[cid]['m8']
    c['mods'] = mm
    for i, (t, intro, pts, ex, act, std) in enumerate(c['mods']):
        mods += (f'<details class="mod" {"open" if i==0 else ""}><summary><span class="mn">Module {i+1}</span> {e(t)} <span class="pill">{H[i]} h</span><span class="pill bz">{BL[i]}</span></summary><p>{e(intro)}</p><ul>' + ''.join(f'<li>{e(p)}</li>' for p in pts) + '</ul>'
                 f'<div class="evi"><strong>Worked example.</strong> {e(ex)}</div><p><strong>Activity.</strong> {e(act)}</p><p><strong>Standard to meet.</strong> {e(std)}</p></details>')
    quiz_t = []
    for q, ans, n in c['quiz']:
        assert 1 <= n <= len(c['mods']), (cid, q, n)
        mt, mstd = c['mods'][n-1][0], c['mods'][n-1][5]
        quiz_t.append((q, ans.rstrip() + f' (Covered in module {n}: {mt}. To pass that module: {mstd.rstrip().rstrip(".")}.)'))
    quiz = ''.join(f'<details class="mod"><summary>Q{i+1}. {e(q)}</summary><p><strong>Model answer:</strong> {e(a)}</p></details>' for i, (q, a) in enumerate(quiz_t))
    rub = ('<div class="scroll-x"><table class="ws-table"><caption>Marking rubric</caption><thead><tr><th>Criterion</th><th>Not yet</th><th>Meets</th><th>Exceeds</th></tr></thead><tbody>' + ''.join(f'<tr><th scope="row">{e(a)}</th><td>{e(b)}</td><td>{e(d)}</td><td>{e(f)}</td></tr>' for a, b, d, f in c['rubric']) + '</tbody></table></div>')
    total = sum(H)
    outs = T[cid]['outs']
    about = B.sec('', 'ab', 'about this course', 'What you will be able to do',
        f'<div class="cb-facts"><span class="pill lv">L4 Practitioner</span><span class="pill">About {total} h</span><span class="pill">Learning Course, 3-6 months</span></div><ul class="blm">' + ''.join(f'<li><span class="bz">{b}</span> {e(t)}</li>' for b, t in outs) + '</ul>'
        f'<h3 class="ws-h3">Task, condition and standard</h3><div class="tcs"><div><h4>Task</h4><p>{e(c["task"])}</p></div><div><h4>Condition</h4><p>{e(T[cid]["cond"])}</p></div><div><h4>Standard</h4><p>{e(T[cid]["std"])}</p></div></div>')
    body = (about + B.sec('alt', 'md', 'lesson by lesson', '8 modules with worked examples', mods)
            + B.sec('', 'as', 'assessment', 'How you are checked', f'<p>Evidence: your practice file, data and decision. A mentor and a peer mark it.</p>{rub}<h3 class="ws-h3">Ten-question check, with model answers</h3>{quiz}')
            + B.sec('alt', 'ld', 'ladder L1 to L7', 'Slide by slide, with notes', '<p>Seven slides, one for each level. Step in at your level and move up; credits stack.</p>' + ladder_html(cid, c, H, BL))
            + B.sec('', 'jb', 'jobs this leads to', 'Where this takes you', '<ul>' + ''.join(f'<li>{e(j)}</li>' for j in c['jobs']) + '</ul>')
            + B.sec('alt', 'lc', 'ten locations and global', 'Your place', '<p>Use local units, rules and authorities.</p>' + ''.join(f'<details class="loc"><summary>{e(L["name"])}</summary><p>Language: {e(L["lang"])}. Currency: {L["cur"]}. Business set-up: {e(L["reg"])}. Personal data: {e(L["data"])}. Product and food rules: {e(L["food"])}.</p></details>' for L in B.LOC))
            + B.sec('', 'nx', 'next', 'Draft', '<p class="ws-note">Draft flagship. Own wording. Process and safety awareness only; no professional advice. Not live.</p>'))
    n = cid.split('-')[1]
    B.page(f'learn-flagship-eu-{n}.html', c['title'] + ' (flagship course)', c['task'][:150], c['title'], e(c['task']), body, B.crumb(('Courses', 'courses-hub.html'), (c['title'], None)), kicker=f'{cid} · flagship course')
for k, v in C.items(): build(k, v)
print('built', len(C))
